import React, { useState } from 'react';
import {
  Home,
  Briefcase,
  FolderOpen,
  Hash,
  Award,
  HelpCircle,
  Star,
  Trophy,
  MessageSquare,
  DollarSign,
  Mail,
  Menu,
  X,
} from 'lucide-react';

export default function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const menuItems = [
    { icon: Home, label: 'HOME', href: '#home' },
    { icon: Briefcase, label: 'SERVICES', href: '#services' },
    { icon: FolderOpen, label: 'PORTFOLIO', href: '#portfolio' },
    { icon: Hash, label: 'NUMERIC', href: '#numeric' },
    { icon: Award, label: 'SKILLS', href: '#skills' },
    { icon: HelpCircle, label: 'FAQS', href: '#faqs' },
  ];

  const experienceItems = [
    { icon: Star, label: 'EXPERIENCE', href: '#experience' },
    { icon: Trophy, label: 'WHAT YOU GET', href: '#what-you-get' },
    { icon: Award, label: 'AWARDS', href: '#awards' },
    { icon: MessageSquare, label: 'TESTIMONIAL', href: '#testimonial' },
    { icon: DollarSign, label: 'PRICING', href: '#pricing' },
    { icon: Mail, label: 'CONTACT FORM', href: '#contact' },
  ];

  return (
    <>
      {/* Top Navigation Bar */}
     <nav className="fixed top-5 left-9 right-9 z-50 bg-black/90 backdrop-blur-sm border-b border-gray-700 px-16 rounded-lx">
        <div className="flex items-center justify-between px-6 py-4 max-w-7xl mx-auto">
          {/* Location */}
          <div className="flex items-center gap-2 text-white">
            <div className="w-2 h-2 bg-green-500 rounded-full"></div>
            <span className="text-sm font-medium">Los Angeles, CA</span>
          </div>

          {/* Brand */}
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 bg-green-500 rounded-full flex items-center justify-center">
              <div className="w-3 h-3 bg-black rounded-full"></div>
            </div>
            <span className="text-white font-semibold text-lg">Portz</span>
          </div>

          {/* Menu Toggle */}
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="w-10 h-10 bg-white rounded-full flex items-center justify-center hover:bg-gray-200 transition-colors"
          >
            {isMenuOpen ? <X className="w-5 h-5 text-black" /> : <Menu className="w-5 h-5 text-black" />}
          </button>
        </div>
      </nav>

      {/* Sidebar Menu Card */}
      <div
        className={`fixed top-19 right-6 w-96 bg-black rounded-2xl border border-gray-700 z-40 transform transition-all duration-300 ${
          isMenuOpen ? 'translate-x-0 opacity-100' : 'translate-x-96 opacity-0'
        }`}
      >
        <div className="p-6 flex space-x-6">
          {/* Menu Section */}
          <div className="flex-1">
            <h3 className="text-white text-sm font-medium mb-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
              Menu
            </h3>
            <ul className="space-y-1">
              {menuItems.map((item, index) => (
                <li key={index}>
                  <a
                    href={item.href}
                    className="flex items-center gap-3 text-gray-200 hover:text-white hover:bg-gray-800/50 transition-all py-2.5 px-3 rounded-lg"
                    onClick={() => setIsMenuOpen(false)}
                  >
                    <item.icon className="w-4 h-4 text-gray-200 group-hover:text-white" />
                    <span className="text-sm font-medium">{item.label}</span>
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Experience Items */}
          <div className="flex-1">
            <h3 className="text-white text-sm font-medium mb-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
              Experience
            </h3>
            <ul className="space-y-1">
              {experienceItems.map((item, index) => (
                <li key={index}>
                  <a
                    href={item.href}
                    className="flex items-center gap-3 text-gray-200 hover:text-white hover:bg-gray-800/50 transition-all py-2.5 px-3 rounded-lg"
                    onClick={() => setIsMenuOpen(false)}
                  >
                    <item.icon className="w-4 h-4 text-gray-200 group-hover:text-white" />
                    <span className="text-sm font-medium">{item.label}</span>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      {/* Overlay */}
      {isMenuOpen && (
        <div
          className="fixed inset-0 bg-black/30 z-30"
          onClick={() => setIsMenuOpen(false)}
        />
      )}
    </>
  );
}
